-- Assertion helper for atomic batches
CREATE VIEW "_assert" AS SELECT 1 AS ok, '' AS msg;
CREATE TRIGGER "_assert_insert" INSTEAD OF INSERT ON "_assert" WHEN NEW.ok IS NOT 1 BEGIN SELECT RAISE(ABORT, NEW.msg); END;
CREATE TRIGGER "_assert_noop" INSTEAD OF INSERT ON "_assert" WHEN NEW.ok IS 1 BEGIN SELECT 1; END;

-- Optimistic locks for atomic batches (tx.lock in lib/db.ts; replaces SELECT … FOR UPDATE)
CREATE TABLE "_locks" ("key" TEXT NOT NULL PRIMARY KEY, "version" INTEGER NOT NULL);

-- Rate-limit counters shared by all Worker instances (lib/rate-store.ts)
CREATE TABLE "_rate_limits" ("key" TEXT NOT NULL PRIMARY KEY, "hits" INTEGER NOT NULL, "resetAt" INTEGER NOT NULL);
